  }

  function routedForGeometry(conn, resolvedRoutes, geometry) {
    const { from, to, start, end, fromSide, toSide } = geometry;
    const authoredPoints = [
      start,
      ...routeVia(conn, from, to, start, end, fromSide, toSide, resolvedRoutes),
      end,
    ];
