import { throwDiagnosticError } from './diagnostics.mjs';
import { rectsOverlap, segmentIntersectsRect } from './geometry.mjs';
import { esc, textUnits } from './utils.mjs';
import { translateMessage } from './i18n.mjs';

const DEFAULT_FONT_SIZE = 8;
const DEFAULT_ITEM_GAP = 22;
const DEFAULT_LINE_GAP = 22;
const DEFAULT_SWATCH_GAP = 8;
const TEXT_ADVANCE_EM = 0.62;
const INTERACTIVE_BADGE_ALLOWANCE = 21;

export function relationshipLegendObstacles(relations, { pointsFor, labelRectFor } = {}) {
  const obstacles = [];
  for (const [index, relation] of (Array.isArray(relations) ? relations : []).entries()) {
    const points = typeof pointsFor === 'function' ? pointsFor(relation, index) : [];
    const finitePoints = (Array.isArray(points) ? points : []).filter((point) => (
      Array.isArray(point) && point.length === 2 && point.every(Number.isFinite)
    ));
    for (let pointIndex = 0; pointIndex < finitePoints.length - 1; pointIndex += 1) {
      obstacles.push({
        kind: 'relationship-segment',
        start: finitePoints[pointIndex],
        end: finitePoints[pointIndex + 1],
      });
    }
    const labelRect = typeof labelRectFor === 'function' ? labelRectFor(relation, index) : null;
    if (labelRect && [labelRect.x, labelRect.y, labelRect.width, labelRect.height].every(Number.isFinite)) {
      obstacles.push({ kind: 'relationship-label', ...labelRect });
    }
  }
  return obstacles;
}

export function resolveLegend(config, catalog, presentKinds) {
  const mode = config?.mode || 'auto';
  if (mode === 'hidden') return [];
  const present = presentKinds instanceof Set ? presentKinds : new Set(presentKinds || []);
  const overrides = config?.entries || {};

  return catalog.flatMap((catalogEntry) => {
    const override = overrides[catalogEntry.kind] || {};
    const selectedByMode = mode === 'all' || present.has(catalogEntry.kind);
    const visible = override.visible === true || (selectedByMode && override.visible !== false);
    if (!visible) return [];
    return [{
      ...catalogEntry,
      label: override.label || catalogEntry.label,
      present: present.has(catalogEntry.kind),
      interactive: catalogEntry.interactive !== false && present.has(catalogEntry.kind),
    }];
  });
}

function measuredEntryWidth(entry, fontSize, swatchGap) {
  const swatchWidth = entry.swatchWidth ?? 14;
  return Math.ceil(
    swatchWidth
    + swatchGap
    + textUnits(entry.label) * fontSize * TEXT_ADVANCE_EM
    + (entry.interactive ? INTERACTIVE_BADGE_ALLOWANCE : 0),
  );
}

// One pure footprint calculation owns both auto-viewBox sizing and final SVG
// placement. Callers must not maintain a second approximation of legend width
// or row count; that would make generated geometry disagree with validation.
export function legendFootprint(entries, {
  width,
  fontSize = DEFAULT_FONT_SIZE,
  itemGap = DEFAULT_ITEM_GAP,
  lineGap = DEFAULT_LINE_GAP,
  swatchGap = DEFAULT_SWATCH_GAP,
} = {}) {
  if (!entries.length) {
    return { measured: [], rows: [], rowCount: 0, minWidth: 0, extraHeight: 0 };
  }
  const measured = entries.map((entry) => ({
    ...entry,
    width: measuredEntryWidth(entry, fontSize, entry.swatchGap ?? swatchGap),
  }));
  const rows = [[]];
  let cursor = 0;
  for (const entry of measured) {
    const row = rows.at(-1);
    const required = (row.length ? itemGap : 0) + entry.width;
    if (row.length && cursor + required > width) {
      rows.push([entry]);
      cursor = entry.width;
    } else {
      row.push(entry);
      cursor += required;
    }
  }
  return {
    measured,
    rows,
    rowCount: rows.length,
    minWidth: measured.reduce((width, entry) => Math.max(width, entry.width), 0),
    extraHeight: (rows.length - 1) * lineGap,
  };
}

export function measureLegend(entries, {
  x,
  baselineY,
  width,
  fontSize = DEFAULT_FONT_SIZE,
  itemGap = DEFAULT_ITEM_GAP,
  lineGap = DEFAULT_LINE_GAP,
  swatchGap = DEFAULT_SWATCH_GAP,
  minTitleY = 0,
  obstacles = [],
  unfit = 'error',
  diagramType = 'diagram',
} = {}) {
  if (!entries.length) return { entries: [], rowCount: 0, titleY: null };
  const footprint = legendFootprint(entries, { width, fontSize, itemGap, lineGap, swatchGap });
  const tooWide = footprint.measured.find((entry) => entry.width > width);
  if (tooWide) {
    if (unfit === 'hide') return null;
    const message = `[legend/label-too-wide] ${diagramType} legend label for "${tooWide.kind}" needs ${tooWide.width}px but only ${width}px is available.`;
    throwDiagnosticError(message, [{
      code: 'legend/label-too-wide',
      severity: 'error',
      message,
      subject: { diagramType, path: `/meta/legend/entries/${tooWide.kind}/label` },
      evidence: { kind: tooWide.kind, measuredWidthPx: tooWide.width, availableWidthPx: width },
      supportedFixes: ['shorten the legend label or use a wider viewBox'],
    }]);
  }

  const titleY = baselineY - footprint.extraHeight - 20;
  const legendTopY = titleY - 10;
  if (legendTopY < minTitleY) {
    if (unfit === 'hide') return null;
    const message = `[legend/vertical-overflow] ${diagramType} legend needs ${footprint.rowCount} rows, which would start at y=${legendTopY} above the available legend band at y=${minTitleY}.`;
    throwDiagnosticError(message, [{
      code: 'legend/vertical-overflow',
      severity: 'error',
      message,
      subject: { diagramType, path: '/meta/legend' },
      evidence: { rowCount: footprint.rowCount, requiredTopY: legendTopY, availableTopY: minTitleY },
      supportedFixes: ['shorten legend labels, hide nonessential entries, or use a wider viewBox'],
    }]);
  }

  const positioned = [];
  footprint.rows.forEach((row, rowIndex) => {
    let entryX = x;
    const baseline = baselineY - (footprint.rowCount - rowIndex - 1) * lineGap;
    for (const entry of row) {
      positioned.push({ ...entry, x: entryX, baseline, row: rowIndex });
      entryX += entry.width + itemGap;
    }
  });

  const legendRects = [
    { kind: 'title', x, y: legendTopY, width: 48, height: 14 },
    ...positioned.map((entry) => ({
      kind: entry.kind,
      x: entry.x,
      y: entry.baseline - 10,
      width: entry.width,
      height: 14,
    })),
  ];
  const collision = legendRects.find((legendRect) => obstacles.some((obstacle) => (
    Array.isArray(obstacle.start) && Array.isArray(obstacle.end)
      ? segmentIntersectsRect({ start: obstacle.start, end: obstacle.end }, legendRect)
      : rectsOverlap(obstacle, legendRect)
  )));
  if (collision) {
    if (unfit === 'hide') return null;
    const message = `[legend/content-overlap] ${diagramType} legend entry "${collision.kind}" overlaps authored relationship geometry.`;
    throwDiagnosticError(message, [{
      code: 'legend/content-overlap',
      severity: 'error',
      message,
      subject: { diagramType, path: '/meta/legend' },
      evidence: { legendKind: collision.kind, legendRect: collision },
      supportedFixes: ['shorten or hide legend entries, use a wider viewBox, or move the authored relationship route/label out of the legend band'],
    }]);
  }

  return {
    entries: positioned,
    rowCount: footprint.rowCount,
    titleY,
    fontSize,
  };
}

export function renderLegend({ entries, layout, renderSwatch, locale }) {
  if (!entries.length) return '';
  const measured = measureLegend(entries, layout);
  if (!measured) return '';
  const hasInteractiveEntries = measured.entries.some((entry) => entry.interactive);
  const renderedFontSize = measured.fontSize < 8 ? measured.fontSize + 0.5 : measured.fontSize + 2;
  const rootAttributes = hasInteractiveEntries ? ' data-legend="" data-legend-bridge=""' : ' data-legend=""';
  const parts = [
    `        <g${rootAttributes}>`,
    `          <text x="${layout.x}" y="${measured.titleY}" class="t-primary" font-size="12" font-weight="650">${esc(translateMessage(locale, 'legend.title'))}</text>`,
  ];

  for (const entry of measured.entries) {
    const interactive = entry.interactive
      ? ` data-legend-kind="${esc(entry.kind)}" data-legend-label="${esc(entry.label)}"`
      : '';
    parts.push(`          <g data-legend-semantic-kind="${esc(entry.kind)}"${interactive} data-legend-x="${entry.x}" data-legend-baseline="${entry.baseline}" data-legend-width="${entry.width}">`);
    parts.push(`            ${renderSwatch(entry)}`);
    parts.push(`            <text x="${entry.x + (entry.swatchWidth ?? 14) + (entry.swatchGap ?? DEFAULT_SWATCH_GAP)}" y="${entry.baseline}" class="t-muted" font-size="${renderedFontSize}" font-weight="500">${esc(entry.label)}</text>`);
    parts.push('          </g>');
  }
  parts.push('        </g>');
  return parts.join('\n');
}

archify/renderers/shared/output-path.mjs.text:
import path from 'node:path';
import {
  containedBy,
  isValidWindowsSmbShareName,
  isWindowsIpcShare,
  resolvePhysicalLocation,
  sameLocation,
} from './path-semantics.mjs';
import { PortablePathError, validatePortablePath } from './portable-path.mjs';

export function canonicalFuturePath(targetPath) {
  const resolution = resolvePhysicalLocation(targetPath);
  if (resolution.status === 'resolved') {
    if (resolution.location.kind === 'existing') return resolution.location.path;
    return path.join(
      resolution.location.ancestorPath,
      ...resolution.location.unresolved,
    );
  }
  const output = path.resolve(targetPath);
  if (resolution.reason.code === 'symlink-cycle') {
    throw new OutputPathError(`Output path contains a symbolic-link cycle: "${output}".`, {
      code: 'output/symlink-cycle',
      message: 'Output path could not be resolved because it contains a symbolic-link cycle.',
      subject: { output },
      evidence: { relation: resolution.reason },
      supportedFixes: ['remove the symbolic-link cycle or choose an output path outside it'],
    });
  }
  throw new OutputPathError('Output path could not be resolved safely.', {
    code: 'output/path-resolution-indeterminate',
    message: 'Output path could not be resolved safely for the requested filesystem location.',
    subject: { output },
    evidence: { relation: resolution.reason },
    supportedFixes: ['use an ordinary local filesystem path that can be resolved safely, then retry'],
  });
}

export function pathsAlias(leftPath, rightPath) {
  const relation = sameLocation(leftPath, rightPath);
  if (relation.status === 'match') return true;
  if (relation.status === 'different') return false;
  if (relation.reason.code === 'ancestor-not-directory') return false;
  if (relation.reason.code === 'symlink-cycle') {
    const output = path.resolve(relation.reason.side === 'right' ? rightPath : leftPath);
    throw new OutputPathError(`Output path contains a symbolic-link cycle: "${output}".`, {
      code: 'output/symlink-cycle',
      message: 'Output path could not be resolved because it contains a symbolic-link cycle.',
      subject: { output },
      evidence: { relation: relation.reason },
      supportedFixes: ['remove the symbolic-link cycle or choose an output path outside it'],
    });
  }
  throw new OutputPathError('Path identity could not be determined safely.', {
    code: 'output/path-identity-indeterminate',
    message: 'Path identity could not be determined safely for the requested filesystem location.',
    subject: { left: path.resolve(leftPath), right: path.resolve(rightPath) },
    evidence: { relation: relation.reason },
    supportedFixes: ['use ordinary local filesystem paths whose identity can be verified, then retry'],
  });
}

function pathIsInside(directoryPath, targetPath) {
  const relation = containedBy(directoryPath, targetPath);
  if (relation.status === 'match') return true;
  if (relation.status === 'different') return false;
  throw new OutputPathError('Output containment could not be determined safely.', {
    code: 'output/containment-indeterminate',
    message: 'Output containment could not be determined safely for the requested filesystem location.',
    subject: { output: path.resolve(targetPath), cwd: path.resolve(directoryPath) },
    evidence: { relation: relation.reason },
    supportedFixes: ['use an output beneath an ordinary local directory whose identity can be verified'],
  });
}

function authoredOutputDiagnostic(error, rawOutput) {
  const absolute = error?.reason === 'absolute';
  const code = absolute ? 'output/meta-absolute' : 'output/meta-path-syntax';
  const message = absolute
    ? 'meta.output must be a relative path resolved from the current working directory.'
    : 'meta.output must be a portable POSIX-relative path.';
  return {
    code,
    message,
    subject: { output: rawOutput, path: '/meta/output' },
    evidence: {
      reason: error?.reason || 'invalid',
      ...(error?.segmentIndex !== undefined ? { segmentIndex: error.segmentIndex } : {}),
      ...(error?.segment !== undefined ? { segment: error.segment } : {}),
      ...(error?.utf8Bytes !== undefined ? { utf8Bytes: error.utf8Bytes } : {}),
      ...(error?.utf16CodeUnits !== undefined ? { utf16CodeUnits: error.utf16CodeUnits } : {}),
      ...(error?.limit !== undefined ? { limit: error.limit } : {}),
    },
    supportedFixes: ['set meta.output to a portable relative .html path such as reports/diagram.html'],
  };
}

function nativeOutputDiagnostic(rawOutput, reason, details = {}) {
  return {
    code: 'output/native-path-syntax',
    message: 'The output path is not a valid native filesystem path on this host.',
    subject: { output: rawOutput },
    evidence: { reason, ...details },
    supportedFixes: ['choose an ordinary filesystem path without device names, alternate data streams, trailing dots or spaces, or overlong components'],
  };
}

function throwNativeOutputDiagnostic(rawOutput, reason, details = {}) {
  const diagnostic = nativeOutputDiagnostic(rawOutput, reason, details);
  throw new OutputPathError(diagnostic.message, diagnostic);
}

function windowsExtendedTailComponents(rawOutput, tail) {
  const authoredComponents = tail.split('\\');
  // Preserve one trailing separator for directory arguments, but never repair
  // an empty component inside the raw extended namespace.
  if (authoredComponents.slice(0, -1).some((component) => component.length === 0)) {
    throwNativeOutputDiagnostic(rawOutput, 'windows-extended-root');
  }
  return authoredComponents.filter(Boolean);
}

function rejectWindowsIpcShare(rawOutput, share) {
  if (isWindowsIpcShare(share)) {
    throwNativeOutputDiagnostic(rawOutput, 'windows-ipc-namespace', { share });
  }
}

function validateWindowsNativeComponent(
  rawOutput,
  component,
  componentIndex,
  { allowReservedName = false } = {},
) {
  try {
    // Prefix the component so a colon is classified as an ADS separator,
    // rather than allowing the generic URI detector to claim it first.
    validatePortablePath(`native/${component}`, { profile: 'output' });
  } catch (error) {
    if (!(error instanceof PortablePathError)) throw error;
    if (allowReservedName && error.reason === 'windows-reserved-name') return;
    // Native Windows arguments may intentionally name an existing 8.3 alias.
    // Portable authored/archive paths reject that ambiguous spelling, while
    // native resolution lets the filesystem prove the existing target.
    if (error.reason === 'windows-short-name') {
      if (component.length <= 255) return;
      throwNativeOutputDiagnostic(rawOutput, 'component-too-long', {
        component,
        componentIndex,
        utf16CodeUnits: component.length,
        limit: 255,
      });
    }
    // Native Windows filesystems bound components in UTF-16 code units. The
    // stricter UTF-8 bound belongs to portable authored/archive names only.
    if (error.reason === 'component-too-long' && error.utf16CodeUnits <= 255) return;
    throwNativeOutputDiagnostic(rawOutput, error.reason, {
      component,
      componentIndex,
      ...(error.character !== undefined ? { character: error.character } : {}),
      ...(error.utf8Bytes !== undefined ? { utf8Bytes: error.utf8Bytes } : {}),
      ...(error.utf16CodeUnits !== undefined ? { utf16CodeUnits: error.utf16CodeUnits } : {}),
      ...(error.limit !== undefined ? { limit: error.limit } : {}),
    });
  }
}

function validateWindowsUncRootComponents(rawOutput, server, share) {
  rejectWindowsIpcShare(rawOutput, share);
  if (!isValidWindowsSmbShareName(share)) {
    throwNativeOutputDiagnostic(rawOutput, 'windows-unc-share-name', {
      share,
      utf16CodeUnits: share.length,
      limit: 80,
    });
  }
  // UNC servers and shares are root components, not DOS file names. Keep the
  // server's ordinary native syntax checks while allowing names such as CON.
  validateWindowsNativeComponent(rawOutput, server, 0, { allowReservedName: true });
}

function windowsExtendedPathComponents(rawOutput) {
  // The extended-length namespace deliberately bypasses Win32 normalization.
  // Inspect its original spelling so a dot segment cannot retarget a UNC share.
  if (rawOutput.includes('/')) {
    throwNativeOutputDiagnostic(rawOutput, 'windows-extended-separator', { character: '/' });
  }
  if (/^\\\\\?\\(?:GLOBALROOT|Device)(?:\\|$)/iu.test(rawOutput)) {
    throwNativeOutputDiagnostic(rawOutput, 'windows-device-namespace');
  }

  const drive = rawOutput.match(/^\\\\\?\\[A-Za-z]:\\/u);
  if (drive) {
    return windowsExtendedTailComponents(rawOutput, rawOutput.slice(drive[0].length));
  }

  const uncPrefix = rawOutput.match(/^\\\\\?\\UNC\\/iu);
  if (uncPrefix) {
    const authoredTail = rawOutput.slice(uncPrefix[0].length);
    const components = authoredTail.split('\\');
    if (components.length < 2 || components[0].length === 0 || components[1].length === 0) {
      throwNativeOutputDiagnostic(rawOutput, 'windows-extended-root');
    }
    validateWindowsUncRootComponents(rawOutput, components[0], components[1]);
    return windowsExtendedTailComponents(rawOutput, components.slice(2).join('\\'));
  }

  throwNativeOutputDiagnostic(rawOutput, 'windows-extended-root');
}

function validateWindowsRawUncRoot(rawOutput) {
  if (!/^[\\/]{2}/u.test(rawOutput) || /^[\\/]{2}[.?][\\/]/u.test(rawOutput)) return;
  // Validate the raw server/share boundary before win32.normalize can collapse
  // an empty share or mix the two UNC separator spellings.
  const unc = rawOutput.match(/^([\\/])\1([^\\/]+)\1([^\\/]+)(?:[\\/]|$)/u);
  if (!unc) {
    throwNativeOutputDiagnostic(rawOutput, 'windows-unc-root');
  }
  validateWindowsUncRootComponents(rawOutput, unc[2], unc[3]);
}

function windowsPathComponents(rawOutput, normalized) {
  const authoredUncPrefix = /^[\\/]{2}/u.test(rawOutput);
  if (/^\\\\\.\\/u.test(normalized)) {
    throwNativeOutputDiagnostic(rawOutput, 'windows-device-namespace');
  }
  if (/^\\\\\?\\/u.test(normalized)) {
    throwNativeOutputDiagnostic(rawOutput, 'windows-extended-root');
  }
  if (normalized.startsWith('\\\\')) {
    const unc = normalized.match(/^\\\\([^\\]+)\\([^\\]+)(?:\\|$)/u);
    if (!unc) throwNativeOutputDiagnostic(rawOutput, 'windows-unc-root');
    return normalized.slice(unc[0].length).split('\\').filter(Boolean);
  }
  if (authoredUncPrefix) throwNativeOutputDiagnostic(rawOutput, 'windows-unc-root');
  if (normalized.startsWith('\\')) {
    throwNativeOutputDiagnostic(rawOutput, 'current-drive-rooted');
  }
  const root = path.win32.parse(normalized).root;
  return normalized
    .slice(root.length)
    .split(/[\\/]+/u)
    // normalize() retains leading navigation for a relative path. Those dot
    // segments are path syntax, not filename components subject to name rules.
    .filter((component) => component && component !== '.' && component !== '..');
}

/**
 * Validate command-line/default output paths using the active host's native
 * syntax. Unlike authored portable paths, absolute paths and native separators
 * remain supported. File outputs reject a trailing separator before native
 * resolution can erase it; directory callers must opt in explicitly. The
 * component bound also protects derived sidecars from failing after an
 * operation has already started mutating the destination.
 */
export function validateNativeOutputPath(
  rawOutput,
  { platform = process.platform, kind = 'file' } = {},
) {
  if (kind !== 'file' && kind !== 'directory') {
    throw new TypeError(`Unsupported native output path kind: ${JSON.stringify(kind)}`);
  }
  if (typeof rawOutput !== 'string' || rawOutput.length === 0) {
    throwNativeOutputDiagnostic(rawOutput, 'empty');
  }
  if (rawOutput.includes('\0')) throwNativeOutputDiagnostic(rawOutput, 'nul-character');
  if (/[\uD800-\uDFFF]/u.test(rawOutput)) {
    throwNativeOutputDiagnostic(rawOutput, 'unpaired-surrogate');
  }
  const hasTrailingSeparator = platform === 'win32'
    ? /[\\/]$/u.test(rawOutput)
    : rawOutput.endsWith(path.posix.sep);
  if (kind === 'file' && hasTrailingSeparator) {
    throwNativeOutputDiagnostic(rawOutput, 'trailing-separator', { kind });
  }

  let normalized;
  let components;
  if (platform === 'win32') {
    if (/^[A-Za-z]:(?:$|[^\\/])/u.test(rawOutput)) {
      throwNativeOutputDiagnostic(rawOutput, 'drive-relative');
    }
    const extendedPrefix = rawOutput.startsWith('\\\\?\\');
    if (extendedPrefix) {
      components = windowsExtendedPathComponents(rawOutput);
    } else {
      validateWindowsRawUncRoot(rawOutput);
      normalized = path.win32.normalize(rawOutput);
      components = windowsPathComponents(rawOutput, normalized);
    }
    for (const [componentIndex, component] of components.entries()) {
      validateWindowsNativeComponent(rawOutput, component, componentIndex);
    }
  } else {
    normalized = path.resolve(rawOutput);
    const root = path.parse(normalized).root;
    components = normalized.slice(root.length).split(path.sep).filter(Boolean);
    for (const [componentIndex, component] of components.entries()) {
      const utf8Bytes = Buffer.byteLength(component, 'utf8');
      if (utf8Bytes > 255) {
        throwNativeOutputDiagnostic(rawOutput, 'component-too-long', {
          component,
          componentIndex,
          utf8Bytes,
          limit: 255,
        });
      }
    }
  }
  return rawOutput;
}

/** Validate a CLI directory argument before native resolution can normalize away its raw syntax. */
export function resolveNativeOutputDirectory(
  rawDirectory,
  { platform = process.platform, cwd = process.cwd() } = {},
) {
  validateNativeOutputPath(rawDirectory, { platform, kind: 'directory' });
  const pathApi = platform === 'win32' ? path.win32 : path.posix;
  return pathApi.resolve(cwd, rawDirectory);
}

export function validateAuthoredOutputPath(rawOutput, { cwd = process.cwd() } = {}) {
  try {
    validatePortablePath(rawOutput, { profile: 'output' });
  } catch (error) {
    if (!(error instanceof PortablePathError)) throw error;
    const diagnostic = authoredOutputDiagnostic(error, rawOutput);
    throw new OutputPathError(diagnostic.message, diagnostic);
  }
  if (path.posix.extname(rawOutput).toLowerCase() !== '.html') {
    throw new OutputPathError('meta.output must target an .html file.', {
      code: 'output/meta-extension',
      message: 'meta.output must target an .html file.',
      subject: { output: rawOutput, path: '/meta/output' },
      supportedFixes: ['change meta.output to a portable path ending in .html'],
    });
  }
  const outputPath = path.resolve(cwd, rawOutput);
  if (path.extname(canonicalFuturePath(outputPath)).toLowerCase() !== '.html') {
    throw new OutputPathError('meta.output must resolve to an .html file.', {
      code: 'output/meta-resolved-extension',
      message: 'meta.output must resolve to an .html file after symbolic links are followed.',
      subject: { output: rawOutput },
      supportedFixes: ['remove the symbolic-link alias or point it to an .html target inside the current working directory'],
    });
  }
  if (!pathIsInside(cwd, outputPath)) {
    throw new OutputPathError('meta.output must stay inside the current working directory.', {
      code: 'output/meta-outside-cwd',
      message: 'meta.output must stay inside the current working directory after symbolic links are resolved.',
      subject: { output: rawOutput, cwd: path.resolve(cwd) },
      supportedFixes: ['set meta.output to a relative .html path inside the current working directory'],
    });
  }
  return rawOutput;
}

export class OutputPathError extends Error {
  constructor(message, diagnostic) {
    super(message);
    this.name = 'OutputPathError';
    this.archifyDiagnostics = [{
      severity: 'error',
      subject: {},
      evidence: {},
      supportedFixes: [],
      ...diagnostic,
    }];
  }
}

export function resolveOutputPath({
  requestedOutput,
  authoredOutput,
  defaultOutput,
  inputPaths = [],
  inputDescription = 'an input',
  otherOutputPaths = [],
  cwd = process.cwd(),
  requiredExtension = '.html',
  platform = process.platform,
}) {
  if (authoredOutput !== undefined) validateAuthoredOutputPath(authoredOutput, { cwd });
  const source = requestedOutput !== undefined
    ? 'cli'
    : (authoredOutput !== undefined ? 'meta' : 'default');
  const rawOutput = source === 'cli'
    ? requestedOutput
    : (source === 'meta' ? authoredOutput : defaultOutput);
  if (source !== 'meta') validateNativeOutputPath(rawOutput, { platform, kind: 'file' });
  const outputPath = path.resolve(cwd, rawOutput);
  for (const inputPath of inputPaths) {
    if (!pathsAlias(outputPath, inputPath)) continue;
    throw new OutputPathError(`Output must not replace ${inputDescription}.`, {
      code: 'output/input-alias',
      message: `Output must not replace ${inputDescription}, including through a symbolic-link or future-path alias.`,
      subject: { output: outputPath, input: path.resolve(inputPath) },
      supportedFixes: ['choose an output path that is distinct from every input path'],
    });
  }
  for (const otherOutputPath of otherOutputPaths) {
    if (!pathsAlias(outputPath, otherOutputPath)) continue;
    throw new OutputPathError('Output targets must use distinct paths.', {
      code: 'output/target-alias',
      message: 'Output targets must use distinct paths, including symbolic-link and future-path aliases.',
      subject: { output: outputPath, conflictingOutput: path.resolve(otherOutputPath) },
      supportedFixes: ['choose distinct paths for every generated output'],
    });
  }

  // Keep explicit CLI directories unrestricted, but reject mistaken file types.
  // Alias checks above retain priority when a target would overwrite an input.
  if (source === 'cli') {
    const resolvedOutput = canonicalFuturePath(outputPath);
    const authoredExtension = path.extname(rawOutput).toLowerCase();
    const existingWindowsHtmlAlias = platform === 'win32'
      && requiredExtension === '.html'
      && authoredExtension === '.htm'
      && path.extname(resolvedOutput).toLowerCase() === requiredExtension
      && pathsAlias(outputPath, resolvedOutput);
    const authoredMatches = authoredExtension === requiredExtension || existingWindowsHtmlAlias;
    const resolvedMatches = path.extname(resolvedOutput).toLowerCase() === requiredExtension;
    if (!authoredMatches || !resolvedMatches) {
      const message = `CLI output must ${authoredMatches ? 'resolve to' : 'target'} a ${requiredExtension} file.`;
      throw new OutputPathError(message, {
        code: authoredMatches ? 'output/cli-resolved-extension' : 'output/cli-extension',
        message,
        subject: { output: rawOutput },
        evidence: { resolvedOutput, requiredExtension },
        supportedFixes: [`choose a path ending in ${requiredExtension} whose symbolic-link target also ends in ${requiredExtension}`],
      });
    }
  }

  return {
    outputPath,
    source,
  };
}

archify/renderers/shared/path-semantics..text:
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

const MAX_SYMLINK_DEPTH = 64;
const RECENT_PROBE_NAME_LIMIT = 128;
const recentProbeNames = new Set();
const WINDOWS_SMB_SHARE_FORBIDDEN = /[\u0000-\u001F"\/\\[\]:|<>+=;,?*]/u;

export function isWindowsIpcShare(share) {
  return /^(?:IPC\$|pipe|mailslot)$/iu.test(share);
}

export function isValidWindowsSmbShareName(share) {
  return typeof share === 'string'
    && share.length > 0
    && share.length <= 80
    && !WINDOWS_SMB_SHARE_FORBIDDEN.test(share)
    && !/[ .]$/u.test(share);
}

function result(status, code, details = {}) {
  return {
    status,
    reason: {
      code,
      ...details,
    },
  };
}

function unknown(code, details = {}) {
  return result('unknown', code, details);
}

function systemFailure(code, error, details = {}) {
  return unknown(code, {
    ...details,
    ...(typeof error?.code === 'string' ? { systemCode: error.code } : {}),
    ...(typeof error?.recoveryPath === 'string' ? { recoveryPath: error.recoveryPath } : {}),
    ...(typeof error?.restoredAtTarget === 'boolean'
      ? { restoredAtTarget: error.restoredAtTarget }
      : {}),
  });
}

function hostPath() {
  return process.platform === 'win32' ? path.win32 : path.posix;
}

function absolutePath(input, side, basePath = process.cwd()) {
  if (typeof input !== 'string' || input.length === 0) {
    return {
      ok: false,
      failure: unknown('invalid-path', { side }),
    };
  }

  try {
    const pathApi = hostPath();
    if (pathApi.isAbsolute(input)) return { ok: true, path: input };
    if (pathApi.parse(input).root) {
      return {
        ok: false,
        failure: unknown('drive-relative-path', { side }),
      };
    }
    const separator = basePath.endsWith(pathApi.sep) ? '' : pathApi.sep;
    return { ok: true, path: `${basePath}${separator}${input}` };
  } catch (error) {
    return {
      ok: false,
      failure: systemFailure('invalid-path', error, { side }),
    };
  }
}

function rootFailure(code, side) {
  return {
    ok: false,
    failure: unknown(code, { side }),
  };
}

function splitWindowsExtendedTail(tail, side, { internalRelativeLinkTarget = false } = {}) {
  const authoredSegments = tail.split('\\');
  // A single final separator is harmless, while an internal empty segment
  // would require normalizing a raw extended path before it reaches Windows.
  if (!internalRelativeLinkTarget
    && authoredSegments.slice(0, -1).some((component) => component.length === 0)) {
    return rootFailure('windows-root-invalid', side);
  }
  const segments = authoredSegments.filter(Boolean);
  if (!internalRelativeLinkTarget
    && segments.some((component) => component === '.' || component === '..')) {
    return rootFailure('windows-root-invalid', side);
  }
  return { ok: true, segments };
}

function splitWindowsAbsolute(absolute, side, { internalRelativeLinkTarget = false } = {}) {
  if (/^[\\/]{2}\.[\\/]/u.test(absolute)) {
    return rootFailure('windows-namespace-unsupported', side);
  }
  if (/^[\\/]{2}\?[\\/]/u.test(absolute) && !absolute.startsWith('\\\\?\\')) {
    return rootFailure('windows-namespace-unsupported', side);
  }

  if (absolute.startsWith('\\\\?\\')) {
    if (absolute.includes('/')) return rootFailure('windows-root-invalid', side);
    if (
      /^\\\\\?\\(?:GLOBALROOT|Device)(?:\\|$)/iu.test(absolute)
      || /^\\\\\?\\Volume\{/iu.test(absolute)
    ) {
      return rootFailure('windows-namespace-unsupported', side);
    }

    const extendedUnc = absolute.match(/^(\\\\\?\\UNC\\([^\\]+)\\([^\\]+))(?:\\(.*))?$/iu);
    if (extendedUnc) {
      if (isWindowsIpcShare(extendedUnc[3])) {
        return rootFailure('windows-namespace-unsupported', side);
      }
      if (!isValidWindowsSmbShareName(extendedUnc[3])) {
        return rootFailure('windows-root-invalid', side);
      }
      if ([extendedUnc[2], extendedUnc[3]].some((component) => component === '.' || component === '..')) {
        return rootFailure('windows-root-invalid', side);
      }
      const tail = splitWindowsExtendedTail(
        extendedUnc[4] || '',
        side,
        { internalRelativeLinkTarget },
      );
      if (!tail.ok) return tail;
      return {
        ok: true,
        root: `${extendedUnc[1]}\\`,
        segments: tail.segments,
      };
    }

    const extendedDrive = absolute.match(/^(\\\\\?\\[A-Za-z]:\\)(.*)$/u);
    if (extendedDrive) {
      const tail = splitWindowsExtendedTail(
        extendedDrive[2],
        side,
        { internalRelativeLinkTarget },
      );
      if (!tail.ok) return tail;
      return {
        ok: true,
        root: extendedDrive[1],
        segments: tail.segments,
      };
    }
    return rootFailure('windows-root-invalid', side);
  }

  const unc = absolute.match(/^[\\/]{2}([^\\/]+)[\\/]([^\\/]+)(?:[\\/](.*))?$/u);
  if (unc) {
    if (isWindowsIpcShare(unc[2])) {
      return rootFailure('windows-namespace-unsupported', side);
    }
    if (!isValidWindowsSmbShareName(unc[2])) {
      return rootFailure('windows-root-invalid', side);
    }
    if ([unc[1], unc[2]].some((component) => component === '.' || component === '..')) {
      return rootFailure('windows-root-invalid', side);
    }
    return {
      ok: true,
      root: `\\\\${unc[1]}\\${unc[2]}\\`,
      segments: (unc[3] || '').split(/[\\/]+/u).filter(Boolean),
    };
  }

  const drive = absolute.match(/^([A-Za-z]:)[\\/](.*)$/u);
  if (drive) {
    return {
      ok: true,
      root: `${drive[1]}\\`,
      segments: drive[2].split(/[\\/]+/u).filter(Boolean),
    };
  }
  return rootFailure('windows-root-invalid', side);
}

function splitAbsolute(absolute, side, options) {
  if (process.platform === 'win32') return splitWindowsAbsolute(absolute, side, options);
  const root = path.posix.parse(absolute).root;
  return {
    ok: true,
    root,
    segments: absolute.slice(root.length).split(/\/+/u).filter(Boolean),
  };
}

function statBigInt(targetPath) {
  return fs.statSync(targetPath, { bigint: true });
}

function ordinaryWindowsRoot(extendedRoot) {
  const drive = extendedRoot.match(/^\\\\\?\\([A-Za-z]:\\)$/u);
  if (drive) return drive[1];

  const unc = extendedRoot.match(/^\\\\\?\\UNC\\([^\\]+)\\([^\\]+)\\$/iu);
  return unc ? `\\\\${unc[1]}\\${unc[2]}\\` : null;
}

function hasStableIdentity(stat) {
  return typeof stat?.dev === 'bigint'
    && typeof stat?.ino === 'bigint'
    && stat.ino !== 0n;
}

function compareKnownEntries(left, right, operation) {
  if (hasStableIdentity(left.stat) && hasStableIdentity(right.stat)) {
    const matches = left.stat.dev === right.stat.dev && left.stat.ino === right.stat.ino;
    return result(matches ? 'match' : 'different', matches ? 'file-identity-match' : 'file-identity-different', {
      operation,
      method: 'bigint-stat',
    });
  }

  // path-contract-allow: lexical-capability -- Canonical paths are compared inside the identity primitive.
  if (left.realPath === right.realPath) {
    return result('match', 'native-realpath-match', {
      operation,
      method: 'native-realpath',
    });
  }

  return unknown('file-identity-unavailable', {
    operation,
    method: 'bigint-stat-and-native-realpath',
  });
}

function rememberProbeName(name) {
  recentProbeNames.add(name);
  if (recentProbeNames.size > RECENT_PROBE_NAME_LIMIT) {
    recentProbeNames.delete(recentProbeNames.values().next().value);
  }
}

function probeInterference(message, code = 'ARCHIFY_PROBE_IDENTITY_CHANGED', details = {}) {
  const error = new Error(message);
  error.code = code;
  Object.assign(error, details);
  return error;
}

function sameStableIdentity(left, right) {
  return hasStableIdentity(left)
    && hasStableIdentity(right)
    && left.dev === right.dev
    && left.ino === right.ino;
}

function preserveQuarantinedReplacement(quarantinePath, targetPath) {
  try {
    fs.linkSync(quarantinePath, targetPath);
    return { restoredAtTarget: true };
  } catch {
    // Preserve the quarantined entry when the original name was concurrently
    // occupied or the host cannot create a hard link. Never overwrite either.
    return { restoredAtTarget: false };
  }
}

function removeOwnedProbe(targetPath, expectedStat) {
  let currentStat;
  try {
    currentStat = fs.lstatSync(targetPath, { bigint: true });
  } catch (error) {
    if (error?.code === 'ENOENT') {
      return probeInterference('filesystem probe disappeared before cleanup', 'ARCHIFY_PROBE_MISSING');
    }
    return error;
  }
  if (!sameStableIdentity(expectedStat, currentStat)) {
    return probeInterference('filesystem probe identity changed before cleanup');
  }

  const quarantineName = `.archify-path-semantics-cleanup-${process.pid}-${crypto.randomBytes(10).toString('hex')}`;
  const quarantinePath = path.join(path.dirname(targetPath), quarantineName);
  rememberProbeName(quarantineName);
  try {
    // Move the checked name into a fresh, unpublished quarantine namespace.
    // A replacement introduced after the check is moved rather than deleted.
    fs.renameSync(targetPath, quarantinePath);
  } catch (error) {
    return error;
  }

  let quarantineStat;
  try {
    quarantineStat = fs.lstatSync(quarantinePath, { bigint: true });
  } catch (error) {
    error.recoveryPath = quarantinePath;
    error.restoredAtTarget = false;
    return error;
  }
  if (!sameStableIdentity(expectedStat, quarantineStat)) {
    const recovery = preserveQuarantinedReplacement(quarantinePath, targetPath);
    return probeInterference(
      'filesystem probe identity changed during cleanup',
      'ARCHIFY_PROBE_IDENTITY_CHANGED',
      { recoveryPath: quarantinePath, ...recovery },
    );
  }

  try {
    // The quarantine spelling did not exist before the atomic rename and is
    // never returned to callers. Legitimate target-path replacements therefore
    // remain outside the only namespace we unlink.
    fs.unlinkSync(quarantinePath);
    return null;
  } catch (error) {
    error.recoveryPath = quarantinePath;
    error.restoredAtTarget = false;
    return error;
  }
}

function resolvePlan({ root, segments }, side, depth) {
  if (depth > MAX_SYMLINK_DEPTH) {
    return {
      ok: false,
      failure: unknown('symlink-cycle', { side }),
    };
  }

  let current;
  let currentStat;
  try {
    current = fs.realpathSync.native(root);
  } catch (error) {
    // Node on Windows can report EISDIR while resolving a valid extended
    // filesystem root (for example \\?\C:\). The namespace was already
    // validated by splitWindowsAbsolute, so retain its exact spelling for
    // traversal.
    if (process.platform === 'win32'
      && error?.code === 'EISDIR'
      && ordinaryWindowsRoot(root)) {
      current = root;
    } else {
      return {
        ok: false,
        failure: systemFailure('root-resolution-failed', error, { side }),
      };
    }
  }

  try {
    currentStat = statBigInt(current);
  } catch (error) {
    // The same Node/Windows edge can occur during stat after realpath succeeds.
    // A drive or share root is short enough for its ordinary spelling, while
    // `current` remains namespaced so descendants keep long-path semantics.
    const ordinaryRoot = process.platform === 'win32'
      && error?.code === 'EISDIR'
      ? ordinaryWindowsRoot(root)
      : null;
    if (ordinaryRoot && ordinaryRoot !== current) {
      try {
        currentStat = statBigInt(ordinaryRoot);
      } catch (statError) {
        return {
          ok: false,
          failure: systemFailure('root-resolution-failed', statError, { side }),
        };
      }
    } else {
      return {
        ok: false,
        failure: systemFailure('root-resolution-failed', error, { side }),
      };
    }
  }

  for (let index = 0; index < segments.length; index += 1) {
    const segment = segments[index];
    if (segment === '.') continue;
    if (segment === '..') {
      if (!currentStat.isDirectory()) {
        return {
          ok: false,
          failure: unknown('ancestor-not-directory', { side, segmentIndex: index }),
        };
      }
      try {
        current = fs.realpathSync.native(hostPath().dirname(current));
        currentStat = statBigInt(current);
      } catch (error) {
        return {
          ok: false,
          failure: systemFailure('path-resolution-failed', error, { side, segmentIndex: index }),
        };
      }
      continue;
    }

    const candidate = hostPath().join(current, segment);
    let candidateStat;
    try {
      candidateStat = fs.lstatSync(candidate, { bigint: true });
    } catch (error) {
      if (error?.code === 'ENOENT') {
        if (!currentStat.isDirectory()) {
          return {
            ok: false,
            failure: unknown('ancestor-not-directory', { side, segmentIndex: index }),
          };
        }
        const unresolved = segments.slice(index).filter((item) => item !== '.');
        if (unresolved.includes('..')) {
          return {
            ok: false,
            failure: unknown('future-parent-traversal-indeterminate', {
              side,
              segmentIndex: index,
            }),
          };
        }
        return {
          ok: true,
          existing: false,
          ancestor: {
            realPath: current,
            stat: currentStat,
          },
          unresolved,
        };
      }
      if (error?.code === 'ENOTDIR') {
        return {
          ok: false,
          failure: systemFailure('ancestor-not-directory', error, { side, segmentIndex: index }),
        };
      }
      return {
        ok: false,
        failure: systemFailure('path-resolution-failed', error, { side, segmentIndex: index }),
      };
    }

    if (candidateStat.isSymbolicLink()) {
      let linkPlan;
      try {
        const authoredTarget = fs.readlinkSync(candidate);
        const pathApi = hostPath();
        const internalRelativeLinkTarget = !pathApi.isAbsolute(authoredTarget)
          && !pathApi.parse(authoredTarget).root;
        const parsedTarget = absolutePath(authoredTarget, side, hostPath().dirname(candidate));
        if (!parsedTarget.ok) return parsedTarget;
        const target = splitAbsolute(parsedTarget.path, side, { internalRelativeLinkTarget });
        if (!target.ok) return target;
        linkPlan = {
          root: target.root,
          segments: [...target.segments, ...segments.slice(index + 1)],
        };
      } catch (error) {
        return {
          ok: false,
          failure: systemFailure('symlink-resolution-failed', error, { side, segmentIndex: index }),
        };
      }
      return resolvePlan(linkPlan, side, depth + 1);
    }

    if (index < segments.length - 1 && !candidateStat.isDirectory()) {
      return {
        ok: false,
        failure: unknown('ancestor-not-directory', { side, segmentIndex: index }),
      };
    }

    try {
      current = fs.realpathSync.native(candidate);
      currentStat = statBigInt(current);
    } catch (error) {
      return {
        ok: false,
        failure: systemFailure('path-resolution-failed', error, { side, segmentIndex: index }),
      };
    }
  }

  return {
    ok: true,
    existing: true,
    entry: {
      realPath: current,
      stat: currentStat,
    },
    unresolved: [],
  };
}

function resolveLocation(input, side) {
  const parsed = absolutePath(input, side);
  if (!parsed.ok) return parsed;
  const plan = splitAbsolute(parsed.path, side);
  if (!plan.ok) return plan;
  return resolvePlan(plan, side, 0);
}

function semanticNameEnvelope(name) {
  const names = new Set([name]);
  const pending = [name];
  while (pending.length > 0 && names.size <= 64) {
    const current = pending.shift();
    const candidates = [
      current.normalize('NFC'),
      current.normalize('NFD'),
      current.toLocaleLowerCase('en-US'),
      current.toLocaleUpperCase('en-US'),
    ];
    for (const candidate of candidates) {
      if (names.has(candidate)) continue;
      names.add(candidate);
      pending.push(candidate);
    }
  }
  return names.size <= 64 ? names : null;
}

function semanticEnvelopesOverlap(leftName, rightName) {
  const left = semanticNameEnvelope(leftName);
  const right = semanticNameEnvelope(rightName);
  if (!left || !right) return true;
  for (const spelling of left) {
    if (right.has(spelling)) return true;
  }
  return false;
}

function windowsDeviceName(name) {
  const stem = name.split('.')[0].replace(/[ .]+$/u, '').toUpperCase();
  return /^(?:CON|PRN|AUX|NUL|CONIN\$|CONOUT\$|COM[1-9¹²³]|LPT[1-9¹²³])$/u.test(stem);
}

function futureWindowsNameRisk(leftName, rightName) {
  if (process.platform !== 'win32') return null;
  const windowsShortName = /~[1-9][0-9]*(?:\.|$)/iu;
  if (windowsShortName.test(leftName) || windowsShortName.test(rightName)) {
    return unknown('future-short-name-indeterminate', { method: 'windows-8dot3' });
  }
  if (windowsDeviceName(leftName) || windowsDeviceName(rightName)) {
    return unknown('future-device-name-indeterminate', { method: 'windows-device-name' });
  }
  if (/[ .]$/.test(leftName) || /[ .]$/.test(rightName)) {
    return unknown('future-trim-name-indeterminate', { method: 'windows-trim-alias' });
  }
  return null;
}

/**
 * Resolve one existing or future path through the host filesystem without
 * exposing a string key for identity comparisons.
 */
export function resolvePhysicalLocation(targetPath) {
  const resolution = resolveLocation(targetPath, 'target');
  if (!resolution.ok) return resolution.failure;
  if (resolution.existing) {
    return {
      status: 'resolved',
      location: {
        kind: 'existing',
        path: resolution.entry.realPath,
      },
      reason: {
        code: 'existing-native-realpath',
        method: 'native-realpath',
      },
    };
  }
  return {
    status: 'resolved',
    location: {
      kind: 'future',
      ancestorPath: resolution.ancestor.realPath,
      unresolved: [...resolution.unresolved],
    },
    reason: {
      code: 'future-physical-ancestor',
      method: 'native-realpath',
    },
  };
}

function probeNameAlias(directoryPath, leftName, rightName) {
  if (leftName === rightName) {
    return result('match', 'future-name-exact', { method: 'lexical-exact' });
  }
  if (recentProbeNames.has(leftName) || recentProbeNames.has(rightName)) {
    return result('different', 'internal-probe-name', { method: 'probe-suppression' });
  }
  const windowsRisk = futureWindowsNameRisk(leftName, rightName);
  if (windowsRisk) return windowsRisk;
  if (!semanticEnvelopesOverlap(leftName, rightName)) {
    return result('different', 'future-name-distinct', { method: 'semantic-envelope' });
  }

  const prefix = `.archify-path-semantics-${process.pid}-${crypto.randomBytes(10).toString('hex')}-`;
  const probeName = `${prefix}${leftName}`;
  const lookupName = `${prefix}${rightName}`;
  const componentLength = (name) => process.platform === 'win32'
    ? name.length
    : Buffer.byteLength(name, 'utf8');
  if (componentLength(probeName) > 255 || componentLength(lookupName) > 255) {
    return unknown('future-name-probe-unrepresentable', {
      method: 'direct-filesystem-probe',
      systemCode: 'ENAMETOOLONG',
    });
  }

  let probePath;
  let probeStat;
  let descriptor;
  let comparison;
  let cleanupError;
  try {
    // Probe entries must live directly in the directory being queried. On
    // Windows case sensitivity is per-directory and a child may not inherit it.
    rememberProbeName(probeName);
    rememberProbeName(lookupName);
    probePath = path.join(directoryPath, probeName);
    const lookupPath = path.join(directoryPath, lookupName);
    descriptor = fs.openSync(probePath, 'wx', 0o600);
    probeStat = fs.fstatSync(descriptor, { bigint: true });

    let authoredStat;
    let lookupStat;
    try {
      authoredStat = statBigInt(probePath);
      lookupStat = statBigInt(lookupPath);
    } catch (error) {
      if (error?.code === 'ENOENT') {
        comparison = result('different', 'future-name-different', { method: 'filesystem-probe' });
      } else {
        comparison = systemFailure('future-name-probe-failed', error, { method: 'filesystem-probe' });
      }
    }

    if (!comparison) {
      const identity = compareKnownEntries(
        { realPath: fs.realpathSync.native(probePath), stat: authoredStat },
        { realPath: fs.realpathSync.native(lookupPath), stat: lookupStat },
        'future-name',
      );
      if (identity.status === 'match') {
        comparison = result('match', 'future-name-alias', { method: 'filesystem-probe' });
      } else if (identity.status === 'different') {
        comparison = result('different', 'future-name-different', { method: 'filesystem-probe' });
      } else {
        comparison = identity;
      }
    }
  } catch (error) {
    comparison = systemFailure('future-name-probe-failed', error, { method: 'filesystem-probe' });
  } finally {
    // Pin the inode until cleanup finishes. Once the final handle is closed,
    // an unlinked probe's inode can be reused by a replacement at the same name.
    if (probeStat) cleanupError = removeOwnedProbe(probePath, probeStat);
    if (descriptor !== undefined) {
      try {
        fs.closeSync(descriptor);
      } catch (error) {
        cleanupError = cleanupError ?? error;
      }
    }
  }

  if (cleanupError) {
    return systemFailure('future-name-probe-cleanup-failed', cleanupError, {
      method: 'filesystem-probe',
      ...(comparison ? { comparison: comparison.reason } : {}),
    });
  }
  return comparison;
}

function sidecarCaseKey(component) {
  // The candidate is accepted only after the containing filesystem confirms
  // that the original grapheme and this spelling name the same entry.
  return component.toLocaleUpperCase('en-US').toLocaleLowerCase('en-US');
}

function transformSidecarComponent(directoryPath, component, transform, phase) {
  if (typeof Intl.Segmenter !== 'function') {
    return {
      ok: false,
      failure: unknown('sidecar-unicode-segmentation-unavailable', {
        operation: 'sidecar-namespace-key',
      }),
    };
  }
  const segmenter = new Intl.Segmenter('en-US', { granularity: 'grapheme' });
  const comparisons = new Map();
  const output = [];
  for (const { segment } of segmenter.segment(component)) {
    const candidate = transform(segment);
    if (candidate === segment) {
      output.push(segment);
      continue;
    }
    const cacheKey = `${segment}\0${candidate}`;
    let comparison = comparisons.get(cacheKey);
    if (!comparison) {
      comparison = probeNameAlias(directoryPath, segment, candidate);
      comparisons.set(cacheKey, comparison);
    }
    if (comparison.status === 'unknown') {
      return {
        ok: false,
        failure: unknown(`sidecar-${phase}-semantics-indeterminate`, {
          operation: 'sidecar-namespace-key',
          cause: comparison.reason,
        }),
      };
    }
    output.push(comparison.status === 'match' ? candidate : segment);
  }
  return {
    ok: true,
    component: output.join(''),
  };
}

/**
 * Produce a stable component for a sidecar namespace in one existing
 * directory. The returned string is a collision-domain key, not a canonical
 * path and must never be used to decide whether two filesystem entries match.
 */
export function sidecarNamespaceComponentKey(directoryPath, component) {
  if (typeof component !== 'string' || component.length === 0
    || component === '.' || component === '..'
    || hostPath().basename(component) !== component) {
    return unknown('invalid-sidecar-component', {
      operation: 'sidecar-namespace-key',
    });
  }

  const directory = resolveLocation(directoryPath, 'sidecar-directory');
  if (!directory.ok) return directory.failure;
  if (!directory.existing) {
    return unknown('sidecar-directory-missing', {
      operation: 'sidecar-namespace-key',
    });
  }
  if (!directory.entry.stat.isDirectory()) {
    return unknown('sidecar-parent-not-directory', {
      operation: 'sidecar-namespace-key',
    });
  }

  const normalized = transformSidecarComponent(
    directory.entry.realPath,
    component,
    (segment) => segment.normalize('NFC'),
    'normalization',
  );
  if (!normalized.ok) return normalized.failure;
  const cased = transformSidecarComponent(
    directory.entry.realPath,
    normalized.component,
    sidecarCaseKey,
    'case',
  );
  if (!cased.ok) return cased.failure;
  const renormalized = transformSidecarComponent(
    directory.entry.realPath,
    cased.component,
    (segment) => segment.normalize('NFC'),
    'normalization',
  );
  if (!renormalized.ok) return renormalized.failure;

  return {
    status: 'resolved',
    directoryPath: directory.entry.realPath,
    componentKey: renormalized.component,
    reason: {
      code: 'sidecar-namespace-key',
      method: 'directory-filesystem-probe',
    },
  };
}

function compareUnmaterializedNames(leftName, rightName) {
  if (leftName === rightName) {
    return result('match', 'future-name-exact', { method: 'lexical-exact' });
  }
  const windowsRisk = futureWindowsNameRisk(leftName, rightName);
  if (windowsRisk) return windowsRisk;
  if (!semanticEnvelopesOverlap(leftName, rightName)) {
    return result('different', 'future-name-distinct', { method: 'semantic-envelope' });
  }
  return unknown('future-descendant-semantics-indeterminate', {
    method: 'unmaterialized-directory',
  });
}

function compareFutureLocations(left, right) {
  const ancestor = compareKnownEntries(left.ancestor, right.ancestor, 'future-ancestor');
  if (ancestor.status !== 'match') return ancestor;

  if (left.unresolved.length !== right.unresolved.length) {
    return result('different', 'future-depth-different', {
      operation: 'same-location',
      leftDepth: left.unresolved.length,
      rightDepth: right.unresolved.length,
    });
  }

  let probedSegments = 0;
  for (let index = 0; index < left.unresolved.length; index += 1) {
    const names = index === 0
      ? probeNameAlias(
        left.ancestor.realPath,
        left.unresolved[index],
        right.unresolved[index],
      )
      : compareUnmaterializedNames(left.unresolved[index], right.unresolved[index]);
    if (names.reason.method === 'filesystem-probe') probedSegments += 1;
    if (names.status !== 'match') {
      const { code, ...reasonDetails } = names.reason;
      return result(names.status, code, {
        ...reasonDetails,
        operation: 'same-location',
        segmentIndex: index,
      });
    }
  }

  return result('match', probedSegments > 0 ? 'future-location-alias' : 'future-location-exact', {
    operation: 'same-location',
    method: probedSegments > 0 ? 'filesystem-probe' : 'lexical-exact',
    probedSegments,
  });
}

/**
 * Compare two existing filesystem entries by physical identity.
 * Missing or unidentifiable entries return `unknown`, never `different`.
 */
export function sameEntry(leftPath, rightPath) {
  const left = resolveLocation(leftPath, 'left');
  if (!left.ok) return left.failure;
  const right = resolveLocation(rightPath, 'right');
  if (!right.ok) return right.failure;

  if (!left.existing || !right.existing) {
    return unknown('entry-missing', {
      operation: 'same-entry',
      missing: [
        ...(!left.existing ? ['left'] : []),
        ...(!right.existing ? ['right'] : []),
      ],
    });
  }

  return compareKnownEntries(left.entry, right.entry, 'same-entry');
}

/**
 * Compare two existing or future write targets using the containing filesystem's
 * actual name semantics. Existing hard links and resolved symbolic links match.
 */
export function sameLocation(leftPath, rightPath) {
  const left = resolveLocation(leftPath, 'left');
  if (!left.ok) return left.failure;
  const right = resolveLocation(rightPath, 'right');
  if (!right.ok) return right.failure;

  if (left.existing && right.existing) {
    return compareKnownEntries(left.entry, right.entry, 'same-location');
  }
  if (left.existing !== right.existing) {
    return result('different', 'location-existence-different', {
      operation: 'same-location',
      existing: left.existing ? 'left' : 'right',
    });
  }
  return compareFutureLocations(left, right);
}

/** Compare the physical locations of the two paths' parent directories. */
export function sameParent(leftPath, rightPath) {
  const left = absolutePath(leftPath, 'left');
  if (!left.ok) return left.failure;
  const right = absolutePath(rightPath, 'right');
  if (!right.ok) return right.failure;

  return sameLocation(hostPath().dirname(left.path), hostPath().dirname(right.path));
}

function parentEntry(entry) {
  const parentPath = hostPath().dirname(entry.realPath);
  // path-contract-allow: lexical-capability -- Both values are canonical paths captured by this primitive.
  if (parentPath === entry.realPath) return null;
  try {
    const realPath = fs.realpathSync.native(parentPath);
    return {
      ok: true,
      entry: {
        realPath,
        stat: statBigInt(realPath),
      },
    };
  } catch (error) {
    return {
      ok: false,
      failure: systemFailure('ancestor-resolution-failed', error, {
        operation: 'contained-by',
      }),
    };
  }
}

/**
 * Determine physical containment in an existing directory. The comparison is
 * inclusive and follows links; the target may exist or name a future location.
 */
export function containedBy(directoryPath, targetPath) {
  const directory = resolveLocation(directoryPath, 'directory');
  if (!directory.ok) return directory.failure;
  if (directory.existing && !directory.entry.stat.isDirectory()) {
    return unknown('container-not-directory', { operation: 'contained-by' });
  }

  const target = resolveLocation(targetPath, 'target');
  if (!target.ok) return target.failure;

  if (!directory.existing) {
    if (target.existing) {
      return unknown('container-missing', { operation: 'contained-by' });
    }
    const ancestor = compareKnownEntries(directory.ancestor, target.ancestor, 'contained-by');
    if (ancestor.status !== 'match') return ancestor;
    if (target.unresolved.length < directory.unresolved.length) {
      return result('different', 'future-container-prefix-too-deep', {
        operation: 'contained-by',
      });
    }
    for (let index = 0; index < directory.unresolved.length; index += 1) {
      const segment = index === 0
        ? probeNameAlias(
          directory.ancestor.realPath,
          directory.unresolved[index],
          target.unresolved[index],
        )
        : compareUnmaterializedNames(
          directory.unresolved[index],
          target.unresolved[index],
        );
      if (segment.status === 'match') continue;
      const { code, ...reasonDetails } = segment.reason;
      return result(segment.status, code, {
        ...reasonDetails,
        operation: 'contained-by',
        segmentIndex: index,
      });
    }
    return result('match', 'future-container-prefix-match', {
      operation: 'contained-by',
      target: 'future',
      depth: target.unresolved.length - directory.unresolved.length,
    });
  }

  let current;
  if (!target.existing) {
    current = target.ancestor;
  } else if (target.entry.stat.isDirectory()) {
    current = target.entry;
  } else {
    const parent = parentEntry(target.entry);
    if (!parent?.ok) return parent?.failure ?? unknown('ancestor-resolution-failed', {
      operation: 'contained-by',
    });
    current = parent.entry;
  }

  let depth = 0;
  let identityWasUnknown = false;
  while (current) {
    const comparison = compareKnownEntries(directory.entry, current, 'contained-by');
    if (comparison.status === 'match') {
      return result('match', 'physical-ancestor-match', {
        operation: 'contained-by',
        depth,
        target: target.existing ? 'existing' : 'future',
      });
    }
    if (comparison.status === 'unknown') identityWasUnknown = true;

    const parent = parentEntry(current);
    if (parent === null) break;
    if (!parent.ok) return parent.failure;
    current = parent.entry;
    depth += 1;
  }

  if (identityWasUnknown) {
    return unknown('containment-identity-unavailable', {
      operation: 'contained-by',
      target: target.existing ? 'existing' : 'future',
    });
  }
  return result('different', 'physical-ancestor-not-found', {
    operation: 'contained-by',
    target: target.existing ? 'existing' : 'future',
  });
}

